export function FeatureGrid({
  heading = "{{heading}}",
  columns = "{{columns}}",
  accent = "{{accent}}",
  showIcons = {{showIcons}},
}) {
  const items = [
    { icon: "\u26a1", title: "Instant sync", desc: "Changes appear everywhere within milliseconds." },
    { icon: "\ud83d\udd12", title: "Private by default", desc: "Nothing leaves your workspace unless you say so." },
    { icon: "\ud83d\udcc8", title: "Built-in reporting", desc: "See trends without exporting a single spreadsheet." },
  ];
  return (
    <section style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", padding: 24 }}>
      <h2 style={{ margin: "0 0 20px", fontSize: 24, fontWeight: 700 }}>{heading}</h2>
      <div style={{ display: "grid", gap: 24, gridTemplateColumns: `repeat(${columns}, 1fr)` }}>
        {items.map((item) => (
          <div key={item.title}>
            {showIcons && (
              <span aria-hidden="true" style={{ display: "inline-flex", alignItems: "center", justifyContent: "center",
                width: 40, height: 40, borderRadius: 10, fontSize: 18, marginBottom: 12, background: accent }}>{item.icon}</span>
            )}
            <h3 style={{ margin: "0 0 6px", fontSize: 16, fontWeight: 700 }}>{item.title}</h3>
            <p style={{ margin: 0, fontSize: 14, color: "#241430cc" }}>{item.desc}</p>
          </div>
        ))}
      </div>
    </section>
  );
}
